+  const context = canvas.getContext('2d');
+  context.drawImage(
+    sourceImage,
+    clampedPixels.x,
+    clampedPixels.y,
+    clampedPixels.width,
+    clampedPixels.height,
+    0,
+    0,
+    clampedPixels.width,
+    clampedPixels.height,
+  );
+  const absoluteOutput = resolvePath(root, outputPath);
+  fs.mkdirSync(path.dirname(absoluteOutput), { recursive: true });
+  fs.writeFileSync(absoluteOutput, await canvas.encode('png'));
+}
