function safeReadJson(root, relPath, role, diagnostics) {
  try {
    const target = path.isAbsolute(relPath) ? relPath : path.join(root, relPath);
    if (!fs.existsSync(target)) {
      diagnostics.push({
        code: role + '_load_failed',
        severity: 'critical',
        role,
        path: relPath,
        reason: 'File does not exist',
      });
      return null;
    }
    const data = JSON.parse(fs.readFileSync(target, 'utf8'));
    if (!data || typeof data !== 'object') {
      diagnostics.push({
        code: role + '_malformed',
        severity: 'critical',
        role,
        path: relPath,
        reason: 'Input must be a JSON object',
      });
      return null;
    }
    return data;
  } catch (error) {
    diagnostics.push({
      code: role + '_load_failed',
      severity: 'critical',
      role,
      path: relPath,
      reason: error instanceof Error ? error.message : String(error),
    });
    return null;
  }
}

