    sourcePageRenders = safeReadJson(root, paths.sourcePageRendersIn, 'figureasset_source_page_renders', diagnostics);
    sourceMap = safeReadJson(root, paths.sourceMapIn, 'figureasset_precise_crop_source_map', diagnostics);
  }

  if (diagnostics.length > 0) {
    const manifest = {
