To prevent diff churn and maintain consistency across generated artifacts, all generated JSON arrays (such as `checks` in the validator result, as well as `crop_artifacts`, `source_figure_asset_candidate_metadata_rows`, and `manual_review_rows` in the manifest) must be strictly ordered lexicographically by their ID fields using strict byte-order comparison. We should also add a check to verify that no input diagnostics were recorded so that the validator fails closed if loading fails.

```javascript
function sortByIdByteOrder(array, keyFn) {
  return [...array].sort((a, b) => {
    const ka = String(keyFn(a));
    const kb = String(keyFn(b));
    if (ka < kb) return -1;
    if (ka > kb) return 1;
    return 0;
  });
}

function buildValidator({ root, manifest, readback, generatedAt }) {
  const cropArtifacts = asArray(manifest.crop_artifacts);
  const manualRows = asArray(manifest.manual_review_rows);
  const missingCropFiles = cropArtifacts.filter((row) => !fs.existsSync(resolvePath(root, row.crop?.output_path ?? '')));
  const missingSourceRenderFiles = cropArtifacts.filter((row) => (
    !row.source_page_render?.output_path
    || !fs.existsSync(resolvePath(root, row.source_page_render.output_path))
  ));
  const badCoordinateRows = cropArtifacts.filter((row) => {
    const dims = row.source_page_render?.dimensions_pixels ?? {};
    const bbox = row.bbox?.clamped_pixels ?? {};
    const normalized = row.bbox?.normalized ?? {};
    return !(
      Number.isFinite(dims.width)
      && Number.isFinite(dims.height)
      && dims.width > 0
      && dims.height > 0
      && Number.isFinite(bbox.x_min)
      && Number.isFinite(bbox.y_min)
      && Number.isFinite(bbox.x_max)
      && Number.isFinite(bbox.y_max)
      && bbox.x_min >= 0
      && bbox.y_min >= 0
      && bbox.x_max <= dims.width
      && bbox.y_max <= dims.height
      && bbox.x_max > bbox.x_min
      && bbox.y_max > bbox.y_min
      && normalized.x_min >= 0
      && normalized.y_min >= 0
      && normalized.x_max <= 1
      && normalized.y_max <= 1
    );
  });
  const cropDimensionMismatches = cropArtifacts.filter((row) => {
    const bbox = row.bbox?.clamped_pixels ?? {};
    const crop = row.crop?.dimensions_pixels ?? {};
    return bbox.width !== crop.width || bbox.height !== crop.height;
  });
  const sourceRenderHashMismatches = cropArtifacts.filter((row) => {
    const renderPath = row.source_page_render?.output_path;
    if (!renderPath || !fs.existsSync(resolvePath(root, renderPath))) return false;
    const actual = sha256File(root, renderPath);
    return row.source_page_render?.output_sha256 && actual !== row.source_page_render.output_sha256;
  });
  const noStudentDisplayClaims = [...cropArtifacts, ...manualRows].every((row) => (
    row.student_display_eligible_final === false
    && row.source_figure_accepted_for_student_display === false
    && row.source_visual_receipt_approved === false
    && row.rights_display_allowed === false
  ));
  const manualRowsWithCrop = manualRows.filter((row) => row.crop_output_path !== null);
  const checks = [
    check('schema_version', manifest.schema_version === 'figureasset_wave1_precise_source_crops.v1', {
      schema_version: manifest.schema_version,
    }),
    check('no_external_vlm_calls', manifest.boundary?.external_vlm_calls_performed === 0, {
      external_vlm_calls_performed: manifest.boundary?.external_vlm_calls_performed,
    }),
    check('candidate_only_no_student_display_or_rights_claims', (
      manifest.boundary?.candidate_only === true
      && manifest.summary.student_display_eligible_final_true_count === 0
      && noStudentDisplayClaims
    ), {
      student_display_eligible_final_true_count: manifest.summary.student_display_eligible_final_true_count,
    }),
    check('crop_files_exist', missingCropFiles.length === 0, {
      produced_crop_count: cropArtifacts.length,
      missing_files: missingCropFiles.map((row) => row.crop?.output_path).slice(0, 25),
    }),
    check('source_render_files_exist_for_replay', missingSourceRenderFiles.length === 0, {
      produced_crop_count: cropArtifacts.length,
      missing_files: missingSourceRenderFiles.map((row) => row.source_page_render?.output_path).slice(0, 25),
    }),
    check('coordinate_bounds', badCoordinateRows.length === 0, {
      bad_coordinate_rows: badCoordinateRows.map((row) => row.crop_artifact_id).slice(0, 25),
    }),
    check('crop_dimensions_match_bbox', cropDimensionMismatches.length === 0, {
      mismatched_rows: cropDimensionMismatches.map((row) => row.crop_artifact_id).slice(0, 25),
    }),
    check('source_render_hashes_preserved', sourceRenderHashMismatches.length === 0, {
      mismatched_rows: sourceRenderHashMismatches.map((row) => row.crop_artifact_id).slice(0, 25),
    }),
    check('produced_from_source_page_renders', cropArtifacts.every((row) => (
      row.source_page_render?.source_page_render_id
      && row.source_page_render?.output_path
      && row.candidate_provenance?.source_candidate_bbox_artifact_path === manifest.source_inputs?.candidate_bbox_proposals_path
    )), {
      produced_crop_count: cropArtifacts.length,
    }),
    check('invalid_or_ambiguous_candidates_not_silently_accepted', manualRowsWithCrop.length === 0, {
      manual_review_entry_count: manualRows.length,
      manual_rows_with_crop_count: manualRowsWithCrop.length,
    }),
    check('readback_counts_present', (
      typeof readback === 'string'
      && readback.includes('Produced crop files')
      && readback.includes('Manual-review rows')
    )),
    check('no_input_diagnostics', !manifest.input_diagnostics || manifest.input_diagnostics.length === 0, {
      diagnostic_count: manifest.input_diagnostics?.length ?? 0,
    }),
  ];
  const sortedChecks = sortByIdByteOrder(checks, (row) => row.id);
  const failedChecks = sortedChecks.filter((item) => item.status !== 'pass');
  return {
    schema_version: 'figureasset_wave1_precise_source_crops_validator.v1',
    generated_at: generatedAt,
    generated_by: SCRIPT_PATH,
    summary: {
      validation_status: failedChecks.length === 0 ? 'pass' : 'fail',
      check_count: sortedChecks.length,
      failed_check_count: failedChecks.length,
      produced_crop_count: manifest.summary.produced_crop_count,
      failed_crop_count: manifest.summary.failed_crop_count,
      manual_review_row_count: manifest.summary.manual_review_row_count,
    },
    checks: sortedChecks,
  };
}
